def dispatch(routes, method, path):
    path_found = False
    for route_method, pattern, view in routes:
        params = match(pattern, path)
        if params is None:
            continue
        if route_method == method:
            return view(**params)
        path_found = True
    if path_found:
        return 405, {'error': 'method not allowed'}
    return 404, {'error': 'not found'}

