    if student is None:
        return 404, {'error': 'student not found'}
    student.update({k: v for k, v in data.items() if k in ALLOWED})
    return 200, student

def delete_student(store, raw_id):
    if not raw_id.isdigit():
        return 400, {'error': 'invalid id'}
    student_id = int(raw_id)
    if student_id not in store:
        return 404, {'error': 'student not found'}
    del store[student_id]
    return 204, None
